    fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
    unsigned char *buf = malloc(n?n:1);
    fread(buf,1,n,f); fclose(f);
    fprintf(stderr, "[driver] running input of %ld bytes\n", n);
    int r = test(buf, n);
    fprintf(stderr, "[driver] returned %d\n", r);
