#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
typedef int (*main_fn)(int, char**, char**);
typedef int (*libc_start_main_fn)(main_fn, int, char**, void(*)(void), void(*)(void), void(*)(void), void*);
typedef int (*init_fn)(int*, char***);
typedef int (*test_fn)(const unsigned char*, unsigned long);
static unsigned long INIT_ADDR=0, TEST_ADDR=0;
static FILE* dumpf=NULL;
static void onsig(int s){ char m[64]; int n=snprintf(m,sizeof m,"[shim4] SIGNAL %d\n",s); write(2,m,n); _exit(128+s); }
// interpose fwrite to capture data written to /dev/null (the ClientHello)
size_t fwrite(const void*ptr,size_t sz,size_t nmemb,FILE*stream){
    static size_t (*real)(const void*,size_t,size_t,FILE*)=NULL;
    if(!real) real=dlsym(RTLD_NEXT,"fwrite");
    const char* fn=getenv("CAPTURE_FILE");
    if(fn && sz*nmemb>0){
        if(!dumpf) dumpf=fopen(fn,"ab");
        if(dumpf){ fwrite(ptr,1,sz*nmemb,dumpf); fflush(dumpf); }
    }
    return real(ptr,sz,nmemb,stream);
}
static int wrapped_main(int argc, char **argv, char **envp) {
    signal(SIGSEGV,onsig); signal(SIGABRT,onsig); signal(SIGBUS,onsig); signal(SIGFPE,onsig);
    init_fn init=(init_fn)INIT_ADDR; test_fn test=(test_fn)TEST_ADDR;
    char **a=argv; init(&argc,&a);
    FILE *f=fopen(argv[1],"rb"); if(!f){perror("open");return 2;}
    fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
    unsigned char *buf=malloc(n?n:1); if(fread(buf,1,n,f)!=(size_t)n){} fclose(f);
    int r=test(buf,n);
    fprintf(stderr,"[shim4] returned %d\n",r);
    return 0;
}
int __libc_start_main(main_fn main, int argc, char **ubp_av,
                      void (*init)(void), void (*fini)(void),
                      void (*rtld_fini)(void), void *stack_end) {
    const char *i=getenv("FUZZ_INIT_ADDR"), *t=getenv("FUZZ_TEST_ADDR");
    if(i) INIT_ADDR=strtoul(i,0,0); if(t) TEST_ADDR=strtoul(t,0,0);
    libc_start_main_fn real=(libc_start_main_fn)dlsym(RTLD_NEXT,"__libc_start_main");
    return real(wrapped_main, argc, ubp_av, init, fini, rtld_fini, stack_end);
}
EOF
