static void onsig(int s){ char m[64]; int n=snprintf(m,sizeof m,"[shim4] SIGNAL %d\n",s); write(2,m,n); _exit(128+s); }
// interpose fwrite to capture data written to /dev/null (the ClientHello)
size_t fwrite(const void*ptr,size_t sz,size_t nmemb,FILE*stream){
    static size_t (*real)(const void*,size_t,size_t,FILE*)=NULL;
    if(!real) real=dlsym(RTLD_NEXT,"fwrite");
    const char* fn=getenv("CAPTURE_FILE");
    if(fn && sz*nmemb>0){
